export enum SubtitleFormat {
  SRT = 'srt',
  VTT = 'vtt',
  ASS = 'ass',
  TXT = 'txt'
}

export interface SubtitleItem {
  id: number;
  startTime: string; // HH:MM:SS,mmm
  endTime: string;   // HH:MM:SS,mmm
  text: string;
}

export interface SubtitleFile {
  name: string;
  originalFormat: SubtitleFormat;
  items: SubtitleItem[];
  size: number;
  lastModified: number;
}

export interface ConversionSettings {
  targetFormat: SubtitleFormat;
  offsetSeconds: number;
  encoding: string;
  removeHtmlTags: boolean;
  chineseConversion: 'none' | 's2t' | 't2s';
}

import { SubtitleFormat, SubtitleItem, SubtitleFile } from '../types';

export const parseSRT = (content: string): SubtitleItem[] => {
  const items: SubtitleItem[] = [];
  const blocks = content.trim().split(/\n\s*\n/);

  blocks.forEach((block, index) => {
    const lines = block.split('\n');
    if (lines.length >= 3) {
      const timeLine = lines[1];
      const match = timeLine.match(/(\d{2}:\d{2}:\d{2},\d{3})\s*-->\s*(\d{2}:\d{2}:\d{2},\d{3})/);
      if (match) {
        items.push({
          id: index + 1,
          startTime: match[1],
          endTime: match[2],
          text: lines.slice(2).join('\n')
        });
      }
    }
  });
  return items;
};

export const parseVTT = (content: string): SubtitleItem[] => {
  const items: SubtitleItem[] = [];
  const cleanContent = content.replace('WEBVTT', '').trim();
  const blocks = cleanContent.split(/\n\s*\n/);

  blocks.forEach((block, index) => {
    const lines = block.split('\n');
    let timeLineIdx = lines[0].includes('-->') ? 0 : 1;

    if (lines[timeLineIdx]) {
      const match = lines[timeLineIdx].match(/(\d{2}:\d{2}:\d{2}\.\d{3})\s*-->\s*(\d{2}:\d{2}:\d{2}\.\d{3})/);
      if (match) {
        items.push({
          id: index + 1,
          startTime: match[1].replace('.', ','),
          endTime: match[2].replace('.', ','),
          text: lines.slice(timeLineIdx + 1).join('\n')
        });
      }
    }
  });
  return items;
};

export const generateSRT = (items: SubtitleItem[]): string => {
  return items.map((item, i) => {
    return `${i + 1}\n${item.startTime} --> ${item.endTime}\n${item.text}\n`;
  }).join('\n');
};

export const generateVTT = (items: SubtitleItem[]): string => {
  const body = items.map((item) => {
    const start = item.startTime.replace(',', '.');
    const end = item.endTime.replace(',', '.');
    return `${start} --> ${end}\n${item.text}\n`;
  }).join('\n');
  return `WEBVTT\n\n${body}`;
};

export const generateASS = (items: SubtitleItem[]): string => {
  const header = `[Script Info]
Title: SubFlow Generated
ScriptType: v4.00+
Collisions: Normal
PlayResX: 640
PlayResY: 360

[V4+ Styles]
Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding
Style: Default,Arial,20,&H00FFFFFF,&H000000FF,&H00000000,&H00000000,0,0,0,0,100,100,0,0,1,2,2,2,10,10,10,1

[Events]
Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
`;

  const events = items.map(item => {
    const start = item.startTime.substring(0, 11).replace(',', '.');
    const end = item.endTime.substring(0, 11).replace(',', '.');
    // Basic ASS cleanup (removing newlines or replacing with \N)
    const text = item.text.replace(/\n/g, '\\N');
    return `Dialogue: 0,${start},${end},Default,,0,0,0,,${text}`;
  }).join('\n');

  return header + events;
};

export const applyTimeOffset = (timeStr: string, offsetMs: number): string => {
  const match = timeStr.match(/(\d{2}):(\d{2}):(\d{2}),(\d{3})/);
  if (!match) return timeStr;

  let ms = parseInt(match[4]) + 
           parseInt(match[3]) * 1000 + 
           parseInt(match[2]) * 60000 + 
           parseInt(match[1]) * 3600000;

  ms = Math.max(0, ms + offsetMs);

  const h = Math.floor(ms / 3600000).toString().padStart(2, '0');
  ms %= 3600000;
  const m = Math.floor(ms / 60000).toString().padStart(2, '0');
  ms %= 60000;
  const s = Math.floor(ms / 1000).toString().padStart(2, '0');
  const mss = (ms % 1000).toString().padStart(3, '0');

  return `${h}:${m}:${s},${mss}`;
};

import { GoogleGenAI, Type } from "@google/genai";
import { SubtitleItem } from "../types";

const API_KEY = process.env.API_KEY || "";

export const translateSubtitles = async (items: SubtitleItem[], targetLang: string): Promise<SubtitleItem[]> => {
  if (!API_KEY) return items;

  const ai = new GoogleGenAI({ apiKey: API_KEY });
  const model = 'gemini-3-flash-preview';

  // We process in small chunks to avoid token limits
  const chunkSize = 20;
  const chunks = [];
  for (let i = 0; i < items.length; i += chunkSize) {
    chunks.push(items.slice(i, i + chunkSize));
  }

  const translatedItems: SubtitleItem[] = [];

  for (const chunk of chunks) {
    const prompt = `Translate the following subtitle segments to ${targetLang}. 
    Keep the context but make it sound natural. 
    Return a JSON array of objects with "id" and "text" fields.

    Subtitles:
    ${JSON.stringify(chunk.map(c => ({ id: c.id, text: c.text })))}`;

    try {
      const response = await ai.models.generateContent({
        model,
        contents: prompt,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                id: { type: Type.INTEGER },
                text: { type: Type.STRING }
              },
              required: ["id", "text"]
            }
          }
        }
      });

      const result = JSON.parse(response.text || "[]");
      chunk.forEach(original => {
        const trans = result.find((r: any) => r.id === original.id);
        translatedItems.push({
          ...original,
          text: trans ? trans.text : original.text
        });
      });
    } catch (error) {
      console.error("AI Translation Error:", error);
      translatedItems.push(...chunk);
    }
  }

  return translatedItems;
};

