                      <div key={idx} className="flex items-center justify-between p-4 bg-gray-50 rounded-2xl border border-gray-100 group hover:border-indigo-200 transition-colors">
                        <div className="flex items-center space-x-3 truncate">
                          <span className="bg-indigo-600 text-white text-[10px] px-2 py-0.5 rounded font-bold uppercase">{file.originalFormat}</span>
                          <span className="text-sm font-medium text-gray-700 truncate">{file.name}</span>
                        </div>
                        <button onClick={() => removeFile(idx)} className="text-gray-300 hover:text-red-500 transition-colors">
                          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                            <path fillRule="evenodd" d="M4.293 4.293a1 1 0 011.414 0L10 8.586l4.293-4.293a1 1 0 111.414 1.414L11.414 10l4.293 4.293a1 1 0 01-1.414 1.414L10 11.414l-4.293 4.293a1 1 0 01-1.414-1.414L8.586 10 4.293 5.707a1 1 0 010-1.414z" clipRule="evenodd" />
                          </svg>
                        </button>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}

          {/* Settings View */}
          {activeTab === 'settings' && (
            <div className="space-y-8 animate-fadeIn">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="space-y-3">
                  <label className="text-sm font-bold text-gray-700">{t.targetFormat}</label>
                  <div className="grid grid-cols-3 gap-3">
                    {Object.values(SubtitleFormat).map((fmt) => fmt !== SubtitleFormat.TXT && (
                      <button
                        key={fmt}
                        onClick={() => setSettings({ ...settings, targetFormat: fmt })}
                        className={`py-3 px-4 rounded-xl border-2 font-bold transition-all ${settings.targetFormat === fmt ? 'border-indigo-600 bg-indigo-50 text-indigo-600 shadow-sm' : 'border-gray-50 bg-gray-50 text-gray-400 hover:border-gray-200'}`}
                      >
                        {fmt.toUpperCase()}
                      </button>
                    ))}
                  </div>
                </div>

                <div className="space-y-3">
                  <label className="text-sm font-bold text-gray-700">{t.timeOffset}</label>
                  <div className="flex items-center space-x-4">
                    <input 
                      type="number" 
                      step="0.1"
                      value={settings.offsetSeconds}
                      onChange={(e) => setSettings({ ...settings, offsetSeconds: parseFloat(e.target.value) || 0 })}
                      className="w-full bg-gray-50 border border-gray-100 rounded-xl px-4 py-3 focus:ring-2 focus:ring-indigo-500 focus:outline-none font-medium"
                    />
                    <div className="text-xs text-gray-400 whitespace-nowrap">{t.timeOffsetSub}</div>
                  </div>
                </div>

                <div className="space-y-3">
                  <label className="text-sm font-bold text-gray-700">{t.encoding}</label>
                  <select 
                    value={settings.encoding}
                    onChange={(e) => setSettings({ ...settings, encoding: e.target.value })}
                    className="w-full bg-gray-50 border border-gray-100 rounded-xl px-4 py-3 focus:ring-2 focus:ring-indigo-500 focus:outline-none font-medium"
                  >
                    <option value="UTF-8">UTF-8 (Recommended)</option>
                    <option value="GBK">Simplified Chinese (GBK)</option>
                    <option value="BIG5">Traditional Chinese (BIG5)</option>
                  </select>
                </div>

                <div className="space-y-3 flex flex-col justify-end">
                   <label className="flex items-center space-x-3 cursor-pointer group p-3 bg-gray-50 rounded-xl border border-gray-100 hover:border-indigo-200 transition-all">
                      <input 
                        type="checkbox" 
                        checked={settings.removeHtmlTags}
                        onChange={(e) => setSettings({ ...settings, removeHtmlTags: e.target.checked })}
                        className="w-5 h-5 rounded border-gray-300 text-indigo-600 focus:ring-indigo-500"
                      />
                      <span className="text-sm font-medium text-gray-700">{t.cleanHtml}</span>
                   </label>
                </div>
              </div>

              <div className="pt-8 border-t border-gray-100 flex flex-col sm:flex-row justify-between items-center gap-4">
                 <button 
                  onClick={() => setActiveTab('upload')}
                  className="px-6 py-3 text-sm font-bold text-gray-400 hover:text-indigo-600 transition-colors"
                 >
                   ← {t.backToUpload}
                 </button>
                 <button 
                  onClick={convertAndDownload}
                  disabled={isProcessing}
                  className="w-full sm:w-auto bg-indigo-600 hover:bg-indigo-700 text-white px-10 py-4 rounded-2xl font-bold shadow-xl shadow-indigo-100 transition-all transform hover:-translate-y-1 active:scale-95 disabled:opacity-50"
                 >
                   {isProcessing ? t.processing : `${t.convertAndDownload} (${files.length} ${t.files})`}
                 </button>
              </div>
            </div>
          )}

          {/* Preview / AI View */}
          {activeTab === 'preview' && (
            <div className="space-y-6 animate-fadeIn">
              <div className="flex flex-col lg:flex-row gap-4 mb-6">
                 <div className="flex-1 bg-gradient-to-br from-indigo-50 to-white border border-indigo-100 rounded-3xl p-6 shadow-sm">
                    <div className="flex items-center space-x-3 mb-4">
                       <span className="text-2xl">✨</span>
                       <h3 className="font-bold text-indigo-900">{t.aiPowerups}</h3>
                    </div>
                    <p className="text-sm text-indigo-700/80 mb-6 leading-relaxed">{t.aiDescription}</p>

                    <div className="flex flex-col sm:flex-row gap-4 items-end">
                       <div className="flex-1 space-y-2">
                          <label className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest">{t.translateTo}</label>
                          <select 
                            value={aiTargetLang}
                            onChange={(e) => setAiTargetLang(e.target.value)}
                            className="w-full bg-white border border-indigo-100 rounded-xl px-4 py-2 text-sm focus:ring-2 focus:ring-indigo-500 focus:outline-none"
                          >
                            <option value="Traditional Chinese">繁體中文 (Traditional Chinese)</option>
                            <option value="Simplified Chinese">简体中文 (Simplified Chinese)</option>
                            <option value="English">English</option>
                            <option value="Japanese">日本語 (Japanese)</option>
                            <option value="Korean">한국어 (Korean)</option>
                          </select>
                       </div>
                       <button 
                         onClick={handleAITranslate}
                         disabled={isProcessing}
                         className="whitespace-nowrap bg-indigo-600 text-white px-6 py-2.5 rounded-xl text-sm font-bold hover:bg-indigo-700 transition-all shadow-md hover:shadow-indigo-200 disabled:opacity-50"
                       >
                         {isProcessing ? t.processing : t.translateBtn}
                       </button>
                    </div>
                 </div>
              </div>

              <div className="max-h-[400px] overflow-y-auto border border-gray-100 rounded-2xl bg-white shadow-inner scrollbar-thin scrollbar-thumb-indigo-100">
                 <table className="w-full text-left text-sm">
                    <thead className="sticky top-0 bg-gray-50 text-gray-500 border-b border-gray-100 z-10">
                      <tr>
                        <th className="px-4 py-3 font-bold w-16">{t.tableId}</th>
                        <th className="px-4 py-3 font-bold w-48">{t.tableTime}</th>
                        <th className="px-4 py-3 font-bold">{t.tableContent}</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-50">
                      {(files[0]?.items || []).slice(0, 100).map((item, idx) => (
                        <tr key={idx} className="hover:bg-indigo-50/30 transition-colors">
                          <td className="px-4 py-3 text-gray-400 font-mono">{item.id}</td>
                          <td className="px-4 py-3">
                             <div className="text-[11px] font-mono text-gray-500 leading-tight">
                                {item.startTime} <br/>
                                <span className="text-indigo-300">➜</span> <br/>
                                {item.endTime}
                             </div>
                          </td>
                          <td className="px-4 py-3 text-gray-700 font-medium whitespace-pre-wrap">
                            {item.text}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                 </table>
              </div>
            </div>
          )}
        </div>
      </main>

      <footer className="mt-12 text-gray-400 text-sm pb-8">
        <p>&copy; 2024 {t.footer}</p>
      </footer>

      {isProcessing && (
        <div className="fixed inset-0 bg-indigo-900/10 backdrop-blur-[2px] z-50 flex items-center justify-center">
           <div className="bg-white p-8 rounded-3xl shadow-2xl flex flex-col items-center space-y-6 max-w-sm w-full mx-4 border border-indigo-50">
              <div className="relative">
                <div className="w-16 h-16 border-4 border-indigo-50 border-t-indigo-600 rounded-full animate-spin"></div>
                <div className="absolute inset-0 flex items-center justify-center">
                   <span className="text-indigo-600 text-xs font-bold">AI</span>
                </div>
              </div>
              <div className="text-center">
                <p className="font-bold text-gray-800 text-lg">{t.processing}</p>
                <p className="text-sm text-gray-400 mt-1">{t.placeholder}</p>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default App;
